<?php
require_once __DIR__ . '/../../includes/bootstrap.php';$user=require_role('hospital_admin');$s=db()->prepare("SELECT id,name FROM organizations WHERE owner_user_id=? AND approval_status='approved' ORDER BY id DESC LIMIT 1");$s->execute([$user['id']]);$org=$s->fetch();if(!$org)redirect('dashboard.php');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'add');if($action==='add'){$name=trim((string)($_POST['name']??''));$description=trim((string)($_POST['description']??''));if(mb_strlen($name)<2)$errors[]='Department name must contain at least two characters.';else{try{$s=db()->prepare("INSERT INTO departments (organization_id,name,description,status) VALUES (?,?,?,'active')");$s->execute([$org['id'],$name,$description?:null]);flash('success','Department added. It is now available for appointment requests.');redirect('hospital/departments.php');}catch(PDOException $e){$errors[]='This department may already exist.';}}}elseif($action==='toggle'){$id=(int)($_POST['department_id']??0);db()->prepare("UPDATE departments SET status=IF(status='active','inactive','active') WHERE id=? AND organization_id=?")->execute([$id,$org['id']]);flash('success','Department status updated.');redirect('hospital/departments.php');}}
$s=db()->prepare('SELECT * FROM departments WHERE organization_id=? ORDER BY name');$s->execute([$org['id']]);$departments=$s->fetchAll();$pageTitle='Manage departments';require __DIR__.'/../../includes/header.php';?>
<section class="dashboard-welcome"><div><span class="eyebrow">PROVIDER SETUP</span><h1>Departments & services</h1><p>Maintain the departments patients can choose when requesting an appointment.</p></div><a class="button button-secondary" href="<?= e(url('hospital/dashboard.php')) ?>">← Dashboard</a></section>
<div class="form-panel department-form"><h2>Add a department</h2><?php if($errors): ?><div class="alert alert-error"><?php foreach($errors as $err): ?><?= e($err) ?><br><?php endforeach; ?></div><?php endif; ?><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add"><label>Department name<input name="name" maxlength="120" required placeholder="e.g. Cardiology"></label><label>Description (optional)<textarea name="description" maxlength="500" placeholder="Services provided by this department"></textarea></label><button class="button" type="submit">Add department +</button></form></div>
<div class="table-card department-table"><?php if(!$departments): ?><div class="empty-state"><h3>No departments added</h3><p>Add departments such as General Medicine, Pediatrics, Cardiology, or Dermatology.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Department</th><th>Description</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($departments as $d): ?><tr><td><strong><?= e($d['name']) ?></strong></td><td><?= e($d['description'] ?: '—') ?></td><td><span class="<?= e(status_class($d['status'])) ?>"><?= e(ucfirst($d['status'])) ?></span></td><td><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="department_id" value="<?= (int)$d['id'] ?>"><button class="button button-small button-secondary" type="submit"><?= $d['status']==='active'?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php require __DIR__.'/../../includes/footer.php'; ?>
